import{_ as t,a,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"Category — Update (and Move)","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-category-update","title":"Update (or Move) Category","description":"Mirrors Bagisto admin Catalog → Categories → Edit. Validation is LOCALE-NESTED — `<locale>.slug`, `<locale>.name`, `<locale>.description` (when display_mode requires it) are required. Moving a category is done by sending `parent_id` + `position` on this same endpoint — there is NO separate /move endpoint.","query":"curl -X PUT \\"https://your-domain.com/api/admin/catalog/categories/7\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"locale\\": \\"en\\",\\n    \\"position\\": 2,\\n    \\"attributes\\": [11, 23],\\n    \\"parent_id\\": 1,\\n    \\"status\\": 1,\\n    \\"en\\": {\\n      \\"slug\\": \\"apparel\\",\\n      \\"name\\": \\"Apparel\\",\\n      \\"description\\": \\"Men\'\'s and women\'\'s apparel\\"\\n    }\\n  }\'\\n","variables":"id=7\\n","response":"{\\n  \\"id\\": 7,\\n  \\"name\\": \\"Apparel\\",\\n  \\"slug\\": \\"apparel\\",\\n  \\"position\\": 2\\n}\\n","commonErrors":[{"error":"Validation (422)","cause":"Locale-nested `<locale>.slug` / `<locale>.name` missing, or `<locale>.description` missing when `display_mode` requires it","solution":"Wrap translatable fields under the locale key (e.g. `\\"en\\": { \\"slug\\": ... }`)"},{"error":"Not Found (404)","cause":"Unknown category id","solution":"Verify the id with the listing endpoint"}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/categories/categories-update.md","filePath":"api/rest-api/admin/catalog/categories/categories-update.md","lastUpdated":1787725411000}'),r={name:"api/rest-api/admin/catalog/categories/categories-update.md"};function i(n,e,s,l,c,p){return d(),a("div",null,e[0]||(e[0]=[o('<h1 id="category-—-update-and-move" tabindex="-1">Category — Update (and Move) <a class="header-anchor" href="#category-—-update-and-move" aria-label="Permalink to &quot;Category — Update (and Move)&quot;">​</a></h1><p>Updates an existing category. Mirrors <strong>Catalog → Categories → Edit</strong> in the Bagisto admin panel.</p><p>There is no separate move endpoint. Re-parenting and reordering are part of the ordinary update payload — <code>PUT</code> the category with a new <code>parent_id</code> and <code>position</code>. The admin panel works the same way: both are ordinary editable fields on the category form, not a distinct &quot;move&quot; action.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/categories/{id}</code></td><td>PUT</td></tr></tbody></table><p><code>{id}</code> must be a positive integer.</p><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>locale</code></td><td>string</td><td>no</td><td>Locale being edited (defaults to the app locale).</td></tr><tr><td><code>position</code></td><td>integer</td><td>yes</td><td>Display order.</td></tr><tr><td><code>attributes</code></td><td>integer[]</td><td>yes</td><td>List of filterable attribute ids.</td></tr><tr><td><code>parent_id</code></td><td>integer|null</td><td>no</td><td>New parent — supply to re-parent (move) the category.</td></tr><tr><td><code>status</code></td><td>integer</td><td>no</td><td><code>0</code> / <code>1</code>.</td></tr><tr><td><code>&lt;locale&gt;</code></td><td>object</td><td>yes</td><td><strong>Locale-nested</strong> translatable fields — see below.</td></tr></tbody></table><h3 id="locale-nested-translatable-fields" tabindex="-1">Locale-nested translatable fields <a class="header-anchor" href="#locale-nested-translatable-fields" aria-label="Permalink to &quot;Locale-nested translatable fields&quot;">​</a></h3><p>Translatable fields go inside a key matching the locale code (e.g. <code>&quot;en&quot;</code>):</p><table tabindex="0"><thead><tr><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td><code>slug</code></td><td>Required.</td></tr><tr><td><code>name</code></td><td>Required.</td></tr><tr><td><code>description</code></td><td>Required when <code>display_mode</code> is <code>description_only</code> or <code>products_and_description</code>.</td></tr><tr><td><code>meta_title</code> / <code>meta_description</code> / <code>meta_keywords</code></td><td>Optional SEO fields.</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>200 OK</code>. Same shape as <a href="/api/rest-api/admin/catalog/categories/categories-detail.html"><code>GET /api/admin/catalog/categories/{id}</code></a>.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid Bearer token</td></tr><tr><td><code>404 Not Found</code></td><td>The category does not exist</td></tr><tr><td><code>422 Unprocessable Entity</code></td><td>Locale-nested validation failure</td></tr></tbody></table>',15)]))}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
